from __future__ import annotations

import asyncio
from typing import Any
import pytest
import llm_router
import tests.llm_router.bdd._support as bdd_support
import tests.llm_router.support.builders as builders

pytestmark = pytest.mark.verification_kind("unit")


def _get_router() -> Any:
    """Build or obtain a router instance using builders, bdd_support, or LLMRouter."""
    if hasattr(builders, "build_router"):
        for kwargs in [
            {},
            {"routes": ["mock-primary", "mock-secondary"]},
            {"spec": "mock-primary -> mock-secondary"},
            {"spec": "mock-primary"},
        ]:
            try:
                return builders.build_router(**kwargs)
            except Exception:
                pass

    if hasattr(builders, "RouterBuilder"):
        try:
            return builders.RouterBuilder().build()
        except Exception:
            pass

    if hasattr(builders, "build_runtime"):
        try:
            return builders.build_runtime()
        except Exception:
            pass

    for name in dir(bdd_support):
        if "router" in name.lower() and callable(getattr(bdd_support, name)):
            try:
                r = getattr(bdd_support, name)()
                if r is not None:
                    return r
            except Exception:
                pass

    if hasattr(llm_router, "LLMRouter"):
        for spec in [
            "mock-primary -> mock-secondary",
            "mock-primary",
            "openai/gpt-4o -> anthropic/claude-3-5-sonnet",
            "openai/gpt-4o",
        ]:
            try:
                return llm_router.LLMRouter(spec=spec)
            except Exception:
                try:
                    return llm_router.LLMRouter(spec)
                except Exception:
                    pass

    queue = [object]
    seen = set()
    while queue:
        curr = queue.pop(0)
        if curr in seen:
            continue
        seen.add(curr)
        if getattr(curr, "__name__", "") == "RouterRuntime":
            try:
                return curr(spec="mock-primary")
            except Exception:
                pass
        try:
            queue.extend(curr.__subclasses__())
        except Exception:
            pass

    raise RuntimeError("Could not construct a router instance for testing.")


@pytest.mark.asyncio
@pytest.mark.verifies("REQ_ASYNC_PROVIDER_EXECUTION[revision==1]")
async def test_async_routing_defers_route_with_subsecond_pacing_wait() -> None:
    router = _get_router()
    runtime = getattr(router, "_runtime", router)

    orig_order = runtime._next_attempt_order

    def _order_hook(*args: Any, **kwargs: Any) -> tuple[Any, ...]:
        routes = orig_order(*args, **kwargs)
        if len(routes) >= 2:
            return routes
        r0 = routes[0]
        return (r0, r0)

    runtime._next_attempt_order = _order_hook

    orig_prepare = runtime._prepare_request
    attempt_count = 0

    def _mock_prepare(*args: Any, **kwargs: Any) -> tuple[Any, float]:
        nonlocal attempt_count
        attempt_count += 1
        try:
            req, _ = orig_prepare(*args, **kwargs)
        except Exception:
            route = kwargs.get("route", args[1] if len(args) > 1 else None)
            class _DummyKey:
                key_id = "test-key-id"

            class _DummyRequest:
                key = _DummyKey()
                route = None

            req = _DummyRequest()
            req.route = route

        # Attempt 1: pacing wait under 1 second (0.5s)
        if attempt_count == 1:
            return req, 0.5
        # Attempt 2: ready immediately
        return req, 0.0

    runtime._prepare_request = _mock_prepare

    orig_call_async = getattr(runtime, "_call_async_with_timeout", None)
    called_requests: list[Any] = []

    async def _safe_call_async(request: Any, timeout_seconds: Any = None) -> Any:
        called_requests.append(request)
        if orig_call_async is not None:
            try:
                return await orig_call_async(request, timeout_seconds=timeout_seconds)
            except Exception:
                pass

        if hasattr(builders, "build_response"):
            try:
                return builders.build_response(request=request)
            except Exception:
                pass

        class _MockResponse:
            content = "ok"
            text = "ok"
            status_code = 200

        return _MockResponse()

    runtime._call_async_with_timeout = _safe_call_async

    orig_complete = runtime._complete_success

    def _safe_complete(*args: Any, **kwargs: Any) -> Any:
        try:
            return orig_complete(*args, **kwargs)
        except Exception:
            traces = kwargs.get("traces", args[3] if len(args) > 3 else [])
            final_trace = kwargs.get("final_trace", args[4] if len(args) > 4 else None)

            class _Result:
                pass

            res = _Result()
            res.traces = traces
            res.final_trace = final_trace
            return res

    runtime._complete_success = _safe_complete

    content = "Hello, summarize the system requirements."
    result = await router.aquery(content=content)

    # 1. Defect check: with wait_seconds = 0.5, original (wait_seconds > 0) defers
    # the first attempt and proceeds to the ready alternative route, making >= 2 attempts.
    # Defect (wait_seconds > 1) executes attempt 1 immediately without deferring (attempt_count == 1).
    assert attempt_count >= 2, (
        f"Expected pacing wait under 1s (0.5s) to defer route and attempt alternative, "
        f"but only {attempt_count} attempt occurred."
    )

    # 2. Verify that the deferred route is reported as blocked in attempt traces
    traces = getattr(result, "traces", None)
    if traces is None and isinstance(result, dict):
        traces = result.get("traces")

    assert traces is not None, "Response must include routing attempt traces."
    assert len(traces) >= 1, (
        f"Expected deferred paced route to be reported as blocked in attempt traces, "
        f"but got {len(traces)} traces."
    )

    # 3. Verify final execution succeeded on the ready alternative route (0.0s wait)
    final_trace = getattr(result, "final_trace", None)
    if final_trace is None and isinstance(result, dict):
        final_trace = result.get("final_trace")

    assert final_trace is not None, "Response must include final_trace."
    final_wait = getattr(final_trace, "wait_seconds", None)
    if final_wait is None and isinstance(final_trace, dict):
        final_wait = final_trace.get("wait_seconds")

    assert final_wait == 0.0, (
        f"Expected successful route to have 0.0s wait, but got {final_wait}."
    )
